  `OrgCode` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '机构编码（多租户隔离），NULL表示平台管理层',
  `OrgId` bigint DEFAULT NULL COMMENT '机构ID，关联cert_org_config.id',
